private async recordAudit(
  action:
    | "run.started"
    | "run.resumed"
    | "run.paused"
    | "run.completed"
    | "run.failed"
    | "run.cancelled",
  run: WorkflowRun,
): Promise<void> {
  await this.options.services.audit.record({
    actor: { type: "system", component: "engine" },
    action,
    entityType: "run",
    entityId: run.id,
    runId: run.id,
    ...(run.error ? { rationale: run.error } : {}),
